#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line); // read first line and ignore
    getline(cin, line); // read second line
    // Split the line by pattern "\\([a-zA-Z_]*\\)"
    vector<string> arr1;
    regex pattern("\\([a-zA-Z_]*\\)");
    sregex_token_iterator iter(line.begin(), line.end(), pattern, -1);
    sregex_token_iterator end;
    for (; iter != end; ++iter) {
        arr1.push_back(iter->str());
    }
    int one = 0;
    for (const auto& segment : arr1) {
        // Split by underscores
        stringstream ss(segment);
        string token;
        while (getline(ss, token, '_')) {
            if ((int)token.length() > one) {
                one = token.length();
            }
        }
    }
    int pos = 0;
    int two = 0;
    bool flag = false;
    bool flag1 = false;
    for (size_t x = 0; x < line.length(); x++) {
        char ch = line[x];
        if (ch == '(') {
            flag = true;
        }
        if (ch == ')') {
            flag1 = false;
            flag = false;
        }
        if (flag && isalpha(ch)) {
            if (flag1) continue;
            two++;
            flag1 = true;
        }
        if (ch == '_') {
            flag1 = false;
        }
    }
    cout << one << " " << two << "\n";
    return 0;
}
